// Original synthesized sound; no recordings, CDN, or third-party audio assets.
export function soundState(sim){const e=sim.experience,attenuate=(body)=>{const p=sim.positions[body];return p?1/(1+Math.hypot(p.x+4-sim.player.x,p.y-sim.player.y,p.z+4-sim.player.z)/18):1;};return{hum:sim.paused?0:.025,transport:['moving','auto-evacuate'].includes(sim.mode)&&!sim.paused?.13:0,shutter:['closing','opening'].includes(sim.mode)&&!sim.paused?.1:0,lift:sim.liftActive&&!sim.paused?.1/(1+Math.abs(sim.player.x+4.5)/12):0,door:!sim.paused&&Object.keys(e.doorProgress).some(k=>Math.abs(e.doorProgress[k]-(e.doorTargets[k]?1:0))>.001)? .065:0,attenuate};}
export class FacilityAudio{
 constructor(){this.volume=.28;this.muted=false;this.ctx=null;this.seen=0;this.available=true;}
 async enable(){try{if(!this.ctx){const C=globalThis.AudioContext??globalThis.webkitAudioContext;if(!C)throw Error('AudioContext unavailable');this.ctx=new C();this.master=this.ctx.createGain();this.master.connect(this.ctx.destination);this.voices={};for(const[name,freq,type]of[['hum',48,'sine'],['transport',83,'sawtooth'],['shutter',146,'triangle'],['lift',109,'triangle'],['door',210,'triangle']]){const o=this.ctx.createOscillator(),g=this.ctx.createGain(),filter=this.ctx.createBiquadFilter();o.type=type;o.frequency.value=freq;filter.type='lowpass';filter.frequency.value=480;g.gain.value=0;o.connect(filter).connect(g).connect(this.master);o.start();this.voices[name]={o,g};}}await this.ctx.resume();return true;}catch(e){this.available=false;return false;}}
 update(sim){if(!this.ctx)return;const t=this.ctx.currentTime,s=soundState(sim);this.master.gain.setTargetAtTime(this.muted?0:this.volume,t,.03);for(const[name,v]of Object.entries(this.voices)){let level=s[name];if(name==='transport'&&sim.mode==='moving'){const stage=sim.plan?.stages[sim.stageIndex];level*=stage?.motions.length?Math.max(...stage.motions.map(m=>s.attenuate(m.id))):0;}v.g.gain.setTargetAtTime(level,t,.065);v.o.frequency.setTargetAtTime(({hum:48,transport:83,shutter:146,lift:109,door:210})[name]+(name==='hum'?0:Math.sin(sim.clock*7)*3),t,.08);}const event=sim.experience.events.at(-1);if(event&&event!==this.lastEvent){this.lastEvent=event;if(event.type==='door'||event.type==='dock'||event.type==='warning'){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.value=event.type==='warning'?440:event.type==='dock'?64:170;g.gain.setValueAtTime(.055*s.attenuate(event.body),t);g.gain.exponentialRampToValueAtTime(.0001,t+.18);o.connect(g).connect(this.master);o.start(t);o.stop(t+.2);}}}
}
